<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Pterodactyl\Models\Dezerx\DiscordBotAlert; use Pterodactyl\Models\Dezerx\DiscordBotMember; use Pterodactyl\Services\Dezerx\DiscordBot\Views\Alerts; class AlertMonitor { public const HYSTERESIS = 5; public const INTENTIONAL_WINDOW = 300; private const BUDGET_SECONDS = 50; private const INTENTIONAL = ['server:power.stop', 'server:power.kill', 'server:power.restart', 'server:reinstall', 'server:backup.restore']; public function __construct(private DiscordRest $rest) { } public function run(): array { $summary = ['checked' => 0, 'posted' => 0, 'failed' => 0]; if (!BotConfig::enabled() || !BotConfig::alertsEnabled()) { return $summary; } $started = microtime(true); $ids = DiscordBotAlert::query() ->orderByRaw('checked_at IS NOT NULL') ->orderBy('checked_at') ->orderBy('id') ->pluck('id'); foreach ($ids->chunk(100) as $chunk) { if (microtime(true) - $started > self::BUDGET_SECONDS) { break; } $alerts = DiscordBotAlert::query()->with(['bot', 'server'])->whereIn('id', $chunk->all())->get(); $members = DiscordBotMember::query()->with('user')->whereIn('user_id', $alerts->pluck('user_id')->unique())->get()->keyBy('user_id'); foreach ($alerts as $alert) { if (microtime(true) - $started > self::BUDGET_SECONDS) { break 2; } try { $posted = $this->check($alert, $members->get($alert->user_id)); ++$summary['checked']; $summary['posted'] += $posted; } catch (Throwable $exception) { ++$summary['failed']; Log::warning('discord bot: an alert check failed', ['alert' => $alert->id, 'error' => $exception->getMessage()]); } } } return $summary; } public function check(DiscordBotAlert $alert, ?DiscordBotMember $member): int { if ($alert->bot === null || $alert->server === null || !BotConfig::serves($alert->bot)) { return 0; } $api = $alert->bot->isGlobal() ? ($member === null ? null : ClientApi::for($member)) : ClientApi::forBot($alert->bot); if ($api === null || !$api->usable()) { $this->remember($alert, $alert->state ?? [], $alert->bot->isGlobal() ? 'The person who set this alert up is no longer linked, or their bot key was deleted.' : 'The bot owner\'s API key was deleted.'); return 0; } if (!BotSettings::enabled($alert->bot, 'alerts')) { return 0; } Style::use(Style::for($alert->bot), BotSettings::active($alert->bot)); $server = $this->server($api, $alert); if (is_string($server)) { $this->remember($alert, $alert->state ?? [], $server); return 0; } $live = Servers::resources($api, $server); $previous = (array) ($alert->state ?? []); $state = [ 'hot' => [], 'announced' => (array) ($previous['announced'] ?? []), 'last' => $live['state'], ]; if ($live['usage'] === null && !in_array($live['state'], ['offline', 'suspended'], true)) { $this->remember($alert, ['last' => $previous['last'] ?? null] + $previous, $live['error'] ?? 'The node did not answer.'); return 0; } $percent = Servers::percentages($server, $live['usage']); $wasHot = (array) ($previous['hot'] ?? []); $posted = 0; $errors = null; foreach ($alert->watches() as $metric => $threshold) { $value = $percent[$metric]; if ($value === null) { continue; } $limit = in_array($metric, $wasHot, true) ? $threshold - self::HYSTERESIS : $threshold; if ($value >= $limit) { $state['hot'][] = $metric; } } $fresh = array_values(array_diff($state['hot'], $state['announced'])); if ($state['hot'] !== [] && $fresh !== [] && $this->cooledDown($alert)) { $result = $this->rest->send($alert->bot, $alert->channel_id, Alerts::hot($alert, $server, $state['hot'], $live, $percent)); if ($result['ok']) { $state['announced'] = $state['hot']; $alert->notified_at = CarbonImmutable::now(); ++$posted; } else { $errors = $result['message']; } } elseif ($state['hot'] === [] && $state['announced'] !== []) { $what = implode(', ', array_map(fn (string $metric) => Alerts::LABELS[$metric], $state['announced'])); $result = $this->rest->send($alert->bot, $alert->channel_id, Alerts::recovered($alert, $server, "{$what} dropped back under the limit.")); if ($result['ok']) { ++$posted; } else { $errors = $result['message']; } $state['announced'] = []; } else { $state['announced'] = array_values(array_intersect($state['announced'], $state['hot'])); } if ($alert->offline && $live['state'] === 'offline') { if (($previous['last'] ?? null) === 'running') { $state['suspect'] = true; } elseif (($previous['suspect'] ?? false) === true && $this->cooledDown($alert) && !$this->intentional($api, $server)) { $result = $this->rest->send($alert->bot, $alert->channel_id, Alerts::crashed($alert, $server)); if ($result['ok']) { $alert->notified_at = CarbonImmutable::now(); ++$posted; } else { $errors = $result['message']; } } } $this->remember($alert, $state, $errors); return $posted; } private function server(ClientApi $api, DiscordBotAlert $alert): array|string { $key = 'dezerx:discordbot:alert-server:' . $alert->id; $cached = Cache::get($key); if (is_array($cached)) { return $cached; } $found = Servers::find($api, (string) $alert->server->uuid); if ($found['server'] === null) { return $found['error'] ?? 'The server could not be read.'; } Cache::put($key, $found['server'], 300); return $found['server']; } private function intentional(ClientApi $api, array $server): bool { $response = $api->get('servers/' . $server['id'] . '/activity', ['per_page' => 15, 'sort' => '-timestamp']); if (!$response->ok()) { return true; } $cutoff = CarbonImmutable::now()->subSeconds(self::INTENTIONAL_WINDOW); foreach ((array) ($response->body['data'] ?? []) as $row) { $attributes = (array) ($row['attributes'] ?? []); $when = Format::time($attributes['timestamp'] ?? null); if ($when === null || $when->lt($cutoff)) { continue; } $event = (string) ($attributes['event'] ?? ''); if (in_array($event, self::INTENTIONAL, true)) { return true; } if ($event === 'server:console.command' && preg_match('/^\s*\/?(stop|end|quit|exit|shutdown|restart)\b/i', (string) data_get($attributes, 'properties.command', '')) === 1) { return true; } } $schedules = $api->get('servers/' . $server['id'] . '/schedules'); foreach ($schedules->ok() ? $schedules->items() : [] as $schedule) { $ran = Format::time($schedule['last_run_at'] ?? null); if ($ran !== null && $ran->gte($cutoff)) { return true; } } return false; } private function cooledDown(DiscordBotAlert $alert): bool { return $alert->notified_at === null || $alert->notified_at->lte(CarbonImmutable::now()->subMinutes(max(1, $alert->cooldown))); } private function remember(DiscordBotAlert $alert, array $state, ?string $error): void { $alert->forceFill([ 'state' => $state, 'checked_at' => CarbonImmutable::now(), 'last_error' => $error === null ? null : mb_substr($error, 0, 300), ])->save(); } } 